import jwt
import hmac
import hashlib
import json
import base64
import time
from typing import Optional, Dict, Any, Tuple
from dataclasses import dataclass, field
from enum import Enum


class KeyType(Enum):
    RSA_PUBLIC = "rsa_public"
    HMAC_SECRET = "hmac_secret"


@dataclass
class KeyEntry:
    kid: str
    key_type: KeyType
    key_material: bytes
    algorithm: str
    created_at: float = field(default_factory=time.time)


class KeyStore:
    """Manages signing and verification keys for the auth service."""

    def __init__(self):
        self._keys: Dict[str, KeyEntry] = {}
        self._default_signing_kid: Optional[str] = None

    def register_key(self, kid: str, key_type: KeyType, key_material: bytes, algorithm: str):
        self._keys[kid] = KeyEntry(
            kid=kid,
            key_type=key_type,
            key_material=key_material,
            algorithm=algorithm
        )

    def set_default_signing_key(self, kid: str):
        if kid not in self._keys:
            raise ValueError(f"Key {kid} not registered")
        self._default_signing_kid = kid

    def get_key(self, kid: str) -> Optional[KeyEntry]:
        return self._keys.get(kid)

    def get_signing_key(self) -> Optional[KeyEntry]:
        if self._default_signing_kid:
            return self._keys.get(self._default_signing_kid)
        return None

    def get_verification_key(self, kid: Optional[str], claimed_alg: str) -> Optional[KeyEntry]:
        """Retrieve the appropriate verification key based on kid and algorithm.

        If kid is provided, look up directly. Otherwise, find a key
        that matches the claimed algorithm family.
        """
        if kid and kid in self._keys:
            return self._keys[kid]

        # Fallback: find any key compatible with the claimed algorithm
        for entry in self._keys.values():
            if self._algorithm_compatible(entry, claimed_alg):
                return entry
        return None

    def _algorithm_compatible(self, entry: KeyEntry, claimed_alg: str) -> bool:
        """Check if a key entry is compatible with the claimed algorithm.

        RSA keys work with RS256/RS384/RS512.
        HMAC keys work with HS256/HS384/HS512.
        """
        rsa_algs = {"RS256", "RS384", "RS512"}
        hmac_algs = {"HS256", "HS384", "HS512"}

        if entry.key_type == KeyType.RSA_PUBLIC and claimed_alg in rsa_algs:
            return True
        if entry.key_type == KeyType.HMAC_SECRET and claimed_alg in hmac_algs:
            return True
        return False


class TokenVerifier:
    """Verifies JWT tokens with support for multiple key types."""

    ALLOWED_ALGORITHMS = ["RS256", "RS384", "RS512", "HS256", "HS384", "HS512"]

    def __init__(self, key_store: KeyStore, clock_skew_seconds: int = 30):
        self._key_store = key_store
        self._clock_skew = clock_skew_seconds

    def verify_token(self, token: str) -> Tuple[bool, Optional[Dict[str, Any]], str]:
        """Verify a JWT token and return (success, claims, error_message)."""
        try:
            # Parse header without verification to get kid and alg
            header = self._decode_header(token)
            if not header:
                return (False, None, "Invalid token header")

            claimed_alg = header.get("alg", "")
            kid = header.get("kid")

            # Validate algorithm is in our allowed list
            if claimed_alg not in self.ALLOWED_ALGORITHMS:
                return (False, None, f"Algorithm {claimed_alg} not allowed")

            # Get the appropriate verification key
            key_entry = self._key_store.get_verification_key(kid, claimed_alg)
            if not key_entry:
                return (False, None, "No suitable verification key found")

            # Verify the token using the key material and the TOKEN's claimed algorithm
            claims = jwt.decode(
                token,
                key_entry.key_material,
                algorithms=[claimed_alg],
                options={"require": ["exp", "iat", "sub"]}
            )

            return (True, claims, "")

        except jwt.ExpiredSignatureError:
            return (False, None, "Token expired")
        except jwt.InvalidTokenError as e:
            return (False, None, f"Invalid token: {str(e)}")

    def _decode_header(self, token: str) -> Optional[Dict[str, Any]]:
        try:
            parts = token.split('.')
            if len(parts) != 3:
                return None
            header_b64 = parts[0]
            # Add padding
            padding = 4 - len(header_b64) % 4
            if padding != 4:
                header_b64 += '=' * padding
            header_bytes = base64.urlsafe_b64decode(header_b64)
            return json.loads(header_bytes)
        except Exception:
            return None


class AuthService:
    """Main authentication service handling token issuance and verification."""

    def __init__(self, rsa_public_key: bytes, hmac_secret: bytes):
        self._key_store = KeyStore()

        # Register the RSA public key for verifying externally-issued tokens
        self._key_store.register_key(
            kid="rsa-primary",
            key_type=KeyType.RSA_PUBLIC,
            key_material=rsa_public_key,
            algorithm="RS256"
        )

        # Register HMAC secret for internal service-to-service tokens
        self._key_store.register_key(
            kid="hmac-internal",
            key_type=KeyType.HMAC_SECRET,
            key_material=hmac_secret,
            algorithm="HS256"
        )

        self._key_store.set_default_signing_key("hmac-internal")
        self._verifier = TokenVerifier(self._key_store)

    def issue_internal_token(self, subject: str, extra_claims: Optional[Dict] = None) -> str:
        """Issue an HMAC-signed token for internal service communication."""
        key_entry = self._key_store.get_signing_key()
        if not key_entry:
            raise RuntimeError("No signing key configured")

        now = time.time()
        claims = {
            "sub": subject,
            "iat": int(now),
            "exp": int(now) + 3600,
            "iss": "auth-service",
            "scope": "internal"
        }
        if extra_claims:
            claims.update(extra_claims)

        return jwt.encode(
            claims,
            key_entry.key_material,
            algorithm=key_entry.algorithm,
            headers={"kid": key_entry.kid}
        )

    def verify_request_token(self, token: str) -> Tuple[bool, Optional[Dict], str]:
        """Verify a token from an incoming request."""
        return self._verifier.verify_token(token)

    def verify_internal_token(self, token: str) -> Tuple[bool, Optional[Dict], str]:
        """Verify a token expected to be from an internal service."""
        success, claims, error = self._verifier.verify_token(token)
        if success and claims:
            if claims.get("scope") != "internal":
                return (False, None, "Token is not an internal service token")
            if claims.get("iss") != "auth-service":
                return (False, None, "Token not issued by auth-service")
        return (success, claims, error)
